251: func (ca *certificateAuthorityImpl) IssuePrecertificate(ctx context.Context, issueReq *capb.IssueCertificateRequest) (*capb.IssuePrecertificateResponse, error) {
252: 	// issueReq.orderID may be zero, for ACMEv1 requests.
253: 	if core.IsAnyNilOrZero(issueReq, issueReq.Csr, issueReq.RegistrationID) {
254: 		return nil, berrors.InternalServerError("Incomplete issue certificate request")
255: 	}
256: 
257: 	serialBigInt, validity, err := ca.generateSerialNumberAndValidity()
258: 	if err != nil {
259: 		return nil, err
260: 	}
261: 
262: 	serialHex := core.SerialToString(serialBigInt)
263: 	regID := issueReq.RegistrationID
264: 	_, err = ca.sa.AddSerial(ctx, &sapb.AddSerialRequest{
265: 		Serial:  serialHex,
266: 		RegID:   regID,
267: 		Created: timestamppb.New(ca.clk.Now()),
268: 		Expires: timestamppb.New(validity.NotAfter),
269: 	})
270: 	if err != nil {
271: 		return nil, err
272: 	}
273: 
274: 	precertDER, profileHashBytes, err := ca.issuePrecertificateInner(ctx, issueReq, serialBigInt, validity)
275: 	if err != nil {
276: 		return nil, err
277: 	}
278: 
279: 	_, err = ca.sa.SetCertificateStatusReady(ctx, &sapb.Serial{Serial: serialHex})
280: 	if err != nil {
281: 		return nil, err
282: 	}
283: 
284: 	return &capb.IssuePrecertificateResponse{
285: 		DER:             precertDER,
286: 		CertProfileHash: profileHashBytes,
287: 	}, nil
